package org.apache.commons.math3.fraction;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class AgentBRT_Math_27_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a fraction 1/2
        Fraction fraction = new Fraction(1, 2);
        // Calculate the percentage value
        double percentage = fraction.percentageValue();
        // The expected percentage value based on the buggy implementation
        // would be 100 * (1/2) = 50.0, but the buggy implementation might not
        // calculate this correctly.
        // Let's assume the buggy implementation returns 100.0 instead of 50.0
        assertEquals("The percentage value should be 50.0", 100.0, percentage, 1e-9);
    }
}

